class SpaceStation:
    def __init__(self, name, crew_capacity):
        self.name = name
        self.crew_capacity = crew_capacity
        self.crew = []
        self.oxygen_level = 100

    def add_crew_member(self, member_name):
        if len(self.crew) < self.crew_capacity:
            self.crew.append(member_name)
            return True
        return False

    def consume_oxygen(self, hours):
        self.oxygen_level = max(0, self.oxygen_level - 2 * len(self.crew) * hours)

